let ready = false;
export function ensureElSchema(): void {
  if (ready) return;
  crmDb.exec(`CREATE TABLE IF NOT EXISTS el_incoming_log(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, salesperson_id INTEGER,
      action TEXT NOT NULL, query_kind TEXT, query_hash TEXT, result TEXT, customer_id INTEGER, owner_salesperson_id INTEGER,
      notified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS idx_el_incoming_user ON el_incoming_log(user_id, created_at);
    CREATE TABLE IF NOT EXISTS el_grants(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, customer_id INTEGER NOT NULL,
      source TEXT NOT NULL, granted_at TEXT NOT NULL, expires_at TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS idx_el_grants_user ON el_grants(user_id, customer_id, expires_at);
    -- SEARCH-65b: additive plain-column index for «تماس ورودی داشتم» live search (own customers by salesperson, phone stored normalized 09xxxxxxxxx).
    CREATE INDEX IF NOT EXISTS idx_customers_sp_phone ON customers(salesperson_id, phone);
    -- SEARCH-C: «ارجاع» of another expert's customer (full number only) → owner bell + «تماس با مشتری ارجاعی» on top of the owner's Today (daily-plan dpRefresh).
    CREATE TABLE IF NOT EXISTS el_referrals(id INTEGER PRIMARY KEY AUTOINCREMENT, from_user_id INTEGER NOT NULL, from_salesperson_id INTEGER, customer_id INTEGER NOT NULL,
      owner_salesperson_id INTEGER NOT NULL, owner_user_id INTEGER NOT NULL, day TEXT NOT NULL, created_at TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS idx_el_referrals_owner ON el_referrals(owner_salesperson_id, day);
    CREATE INDEX IF NOT EXISTS idx_el_referrals_from ON el_referrals(from_user_id, created_at);`);
  ready = true;
}

/* ---------------- customer access (a)/(b)/(c) ---------------- */
/** Tehran day bounds, same convention as dci-queue (fixed +03:30, no DST). */
function elTehranDayBounds(now: Date): { start: string; end: string } {
  const day = dpToday(now);
  return { start: new Date(`${day}T00:00:00+03:30`).toISOString(), end: new Date(`${day}T23:59:59.999+03:30`).toISOString() };
}
/** Same mobile key as customerMatcher / normalizePhone (0 + 10 or 11 digits). */
function elPhoneKey(raw: unknown): string | null {
  const n = normalizeCustomerMobile(raw);
  return /^0\d{9,10}$/.test(n) ? n : null;
}
/** Incoming call this expert answered today (or a live incoming still on their extension) — in-scope for the rest of the Tehran day.
 *  Matches the event's customer_id, or (t848u) an unlinked event (customer_id IS NULL) whose phone is this customer's number.
 *  No write: a missed ingest link still opens the same customer for this expert. A different number does not. */
function elAnsweredIncomingToday(u: U, customerId: number, now: Date): boolean {
  if (!queryRow("SELECT 1 x FROM sqlite_master WHERE type='table' AND name='voip_after_call_events'")) return false;
  const { start, end } = elTehranDayBounds(now);
  const evs = queryRows<{ customer_id: number | null; phone: string | null }>(
    `SELECT customer_id, phone FROM voip_after_call_events
      WHERE expert_user_id=?
        AND lower(direction) IN ('incoming','inbound')
        AND (upper(trim(status))='ANSWERED' OR is_live=1)
        AND julianday(started_at)>=julianday(?) AND julianday(started_at)<=julianday(?)`,
    [Number(u.id), start, end],
  );
  if (evs.some((e) => e.customer_id != null && Number(e.customer_id) === Number(customerId))) return true;
  const row = queryRow<{ phone: string | null }>("SELECT phone FROM customers WHERE id=? AND merged_into_customer_id IS NULL", [customerId]);
  const keys = new Set<string>();
  const want = elPhoneKey(row?.phone);
  if (want) keys.add(want);
  try {
    const extras = queryRows<{ phone: string }>("SELECT phone FROM customer_phones WHERE customer_id=?", [customerId]);
    for (const x of extras) { const k = elPhoneKey(x.phone); if (k) keys.add(k); }
  } catch { /* table created lazily */ }
  if (!keys.size) return false;
  return evs.some((e) => { const k = elPhoneKey(e.phone); return e.customer_id == null && k != null && keys.has(k); });
}
export function elCustomerAccess(u: U, customerId: number, now = new Date()): "plan" | "incoming" | "registered" | "case" | "delegated" | null {
  const sp = Number(u.salespersonId);
  if (queryRow("SELECT 1 x FROM sqlite_master WHERE type='table' AND name='dp_items'") &&
      queryRow("SELECT 1 x FROM dp_items i JOIN dp_plans p ON p.id=i.plan_id WHERE p.salesperson_id=? AND p.day=? AND i.customer_id=? LIMIT 1", [sp, dpToday(now), customerId])) return "plan";
  if (elAnsweredIncomingToday(u, customerId, now)) return "incoming";
  ensureElSchema();
  const own = queryRow<{ salesperson_id: number | null }>("SELECT salesperson_id FROM customers WHERE id=? AND merged_into_customer_id IS NULL", [customerId]);
  if (!own) return null;
  if (Number(own.salesperson_id) !== sp) {
    // t927: Hasani (etc.) may open Kazemi/Ghasemi files when flag.bale_view_as_v1 is on and the grant lists those owners. Ownership is unchanged.
    if (bvaCanAccessSalesperson(u, own.salesperson_id)) return "delegated";
    return null;
  }
  if (queryRow("SELECT 1 x FROM el_grants WHERE user_id=? AND customer_id=? AND expires_at>? LIMIT 1", [Number(u.id), customerId, now.toISOString()])) return "incoming";
  // NEWCUST-65 (= incoming2-59 (d)): a customer this expert registered through «تماس ورودی داشتم › ثبت مشتری جدید» (still their own).
  if (queryRow("SELECT 1 x FROM el_incoming_log l JOIN customers c ON c.id=l.customer_id WHERE l.user_id=? AND l.customer_id=? AND l.action='new_create' AND l.result='created' AND c.registered_by=? LIMIT 1",
    [Number(u.id), customerId, Number(u.id)])) return "registered";
  if (queryRow("SELECT 1 x FROM loan_applications WHERE customer_id=? AND deleted_at IS NULL LIMIT 1", [customerId])) return "case";
  if (queryRow("SELECT 1 x FROM goods_purchases WHERE customer_id=? LIMIT 1", [customerId])) return "case";
  if (queryRow("SELECT 1 x FROM sqlite_master WHERE type='table' AND name='customer_payment_orders'") &&
      queryRow("SELECT 1 x FROM customer_payment_orders WHERE customer_id=? LIMIT 1", [customerId])) return "case";
  return null;
}

