/** «حساب شخصی بله» routes (see lib/bale.ts): staff router behind the CRM session under /api; the internal inbound router
 * (sidecar → API, loopback + internal token) is mounted in app.ts outside /api; the runner hook is mounted by routes/assistants.ts. */
import path from "node:path";
import type { Request, Response } from "express";
import type { AuthUser } from "../lib/auth";
import { crmDb, databasePath } from "../lib/crm-db";
import { createBale, ensureBaleSchema } from "../lib/bale";
import { createHttpBaleSidecar } from "../lib/bale-sidecar-client";

ensureBaleSchema(crmDb);
const env = () => process.env;
const bale = createBale({
  db: crmDb, env,
  sidecar: createHttpBaleSidecar(() => ({ ...process.env, BALE_SIDECAR_URL: process.env.BALE_SIDECAR_URL || "http://127.0.0.1:18470" })),
  actor: (res: Response) => { const u = res.locals.authUser as AuthUser | undefined; return u ? { id: u.id } : null; },
  // «فایل طرح برای بله»: next to the DB, never inside the web root.
  planFilesDir: process.env.BALE_PLAN_FILES_DIR || path.join(path.dirname(path.resolve(databasePath)), "bale-plan-files"),
});
// Sender / reminder / re-attach worker. BALE_WORKER=0 turns it off (tests, maintenance).
if (process.env.BALE_WORKER !== "0" && process.env.NODE_ENV !== "test") bale.worker.start();
export const baleInternalRouter = bale.internal;
export const baleRunnerSend = (req: Request, res: Response, h: { inScope: (a: any, customerId: number) => boolean; replyScope?: (a: any, customerId: number) => boolean }) => bale.runnerSend(req, res, h);
export default bale.staff;
export const baleRunnerPlanFiles = (req: Request, res: Response) => bale.runnerPlanFiles(req, res);
type Scope = { inScope: (a: any, customerId: number) => boolean; replyScope?: (a: any, customerId: number) => boolean };
/** «پاسخ خودکار» runner routes (pair-locked; see lib/bale.ts). */
export function mountBaleAutoreplyRunner(runner: import("express").Router, h: Scope) {
  runner.post("/bale/auto-reply", (req, res) => bale.runnerAutoReply(req, res, h));
  runner.get("/bale/auto-reply/state", (req, res) => bale.runnerAutoReplyState(req, res));
  runner.post("/bale/ask-expert", (req, res) => bale.runnerAskExpert(req, res, h));   // AR30
  runner.get("/bale/learned", (req, res) => bale.runnerLearned(req, res));            // AR30
  runner.get("/bale/conversations/:customerId/messages", (req, res) => bale.runnerConversation(req, res, h));
  runner.get("/bale/status", (req, res) => bale.runnerStatus(req, res));          // BALE-STATUS-64 (read-only)
  runner.get("/bale/ar-chats", (req, res) => bale.runnerArChats(req, res));
  runner.get("/bale/ar-chats/:id/messages", (req, res) => bale.runnerArChats(req, res));
  runner.get("/customers/:id/documents", (req, res) => bale.runnerDocuments(req, res, h));
}

/* «فضای کار بله» v1.0 (flag.bale_workspace_v1): the invite's two legs. Nothing here runs unless an expert / manager presses «دعوت به بله»
 * while the flag is ON. Bale = the customer's expert's own connected account through the normal outbox (scope, caps, quiet hours, banned
 * words — expert_command + sendNow, exactly like «بفرست»); never a session (re)connect. SMS = IPPanel PATTERN through the existing local relay
 * (bws.invite_sms_pattern; empty → «not_configured», nothing is sent). No paid / commercial Bale API. */
import { setBwsInviteTransport } from "../lib/bale-workspace";
import { getNotificationSettings } from "../lib/customer-notifications";
import { sendPatternViaRelay } from "../lib/expert-intro-sms-core";
setBwsInviteTransport({
  async bale(o) {
    const a = crmDb.prepare("SELECT id, status FROM bale_accounts WHERE user_id=? AND kind<>'system_test'").get(o.ownerUserId) as { id: number; status: string } | undefined;
    if (!a || a.status !== "connected") return { state: "not_connected" };
    const r = bale._internal.outbox.enqueue({ accountId: a.id, customerId: o.customerId, text: o.text, source: "expert_command", explicit: true, createdBy: o.actorUserId, sendNow: true });
    if (r.status === "blocked") return { state: "blocked", reason: r.reason };
    return { state: "queued", ref: String(r.outboxId) };
  },
  baleState(ref) {
    const o = crmDb.prepare("SELECT status, error FROM bale_outbox WHERE id=?").get(Number(ref)) as { status: string; error: string | null } | undefined;
    if (!o) return { state: "failed" };
    if (o.status === "sent") return { state: "sent" };
    if (o.status === "failed") return { state: o.error === "no_bale_account" ? "no_bale" : "failed" };
    if (o.status === "blocked" || o.status === "cancelled") return { state: "failed" };
    return { state: "queued" };
  },
  async sms(o) {
    if (!o.pattern) return { state: "not_configured" };
    if (process.env.SMS_DISABLED === "1") return { state: "disabled" };
    const s = getNotificationSettings(); if (!s.ippanelEnabled) return { state: "disabled" };
    try {
      const id = await sendPatternViaRelay({ recipient: o.phone, patternCode: o.pattern, params: { name: o.name.trim().slice(0, 80) } },
        { relayUrl: s.ippanelRelayUrl, fromNumber: s.ippanelFromNumber, secret: process.env.IR_RELAY_SHARED_SECRET });
      return { state: "sent", ref: id };
    } catch { return { state: "failed" }; }
  },
});
